#!/usr/bin/env python3
# apply_reliability_gate.py — ── RELIABILITY_GATE_20261118 ── (TD-048, TD-049)
#
# Diff-triggered reliability checklist + commit gate, as a pre-commit commit-msg hook.
#   * 14 checklist items (scripts/checklist/items.py), each with a trigger read from the
#     staged diff, a check, and the incidents behind it; only triggered items run.
#   * Gate modes off / observe / enforce (scripts/checklist/MODE) — starts in OBSERVE:
#     never blocks, stamps "Checklist: …" on each commit, logs to .git/scalp-gate.log.
#   * The items and the mode are read from HEAD, so a commit cannot loosen its own checks.
#
#   python3 apply_reliability_gate.py              apply (run from the repo root)
#   python3 apply_reliability_gate.py --rollback   put everything back exactly
#
# Adds:     scripts/checklist/items.py, scripts/checklist/MODE,
#           scripts/hooks/reliability_checklist.py, scripts/test_reliability_checklist.py
# Changes:  .pre-commit-config.yaml (5th hook, commit-msg hook type), scripts/test_precommit_hooks.py
#           (TC-HOOKS-0026/0027), CLAUDE.md (one section)
# Then:     runs `pre-commit install` if pre-commit is set up here, so the commit-msg hook is live.
# Stdlib only. Idempotent: a second run says "already applied" and changes nothing.
import base64
import json
import os
import py_compile
import shutil
import subprocess
import sys
import tempfile
import zlib

FENCE = "RELIABILITY_GATE_20261118"
PARENT = "PUSH_ANYTIME_20261118"
BAK = ".bak-" + FENCE
EDITS = json.loads(base64.b64decode("").decode("utf-8"))
NEW = {p: zlib.decompress(base64.b64decode(b)).decode("utf-8") for p, b in json.loads(
    base64.b64decode("").decode("utf-8")).items()}
EXEC = {"scripts/hooks/reliability_checklist.py", "scripts/test_reliability_checklist.py"}
HOOK = os.path.join(".git", "hooks", "commit-msg")
CREATED_MARK = os.path.join(".git", "hooks", "commit-msg" + ".created-" + FENCE)


def say(m):
    print(m, flush=True)


def die(m):
    say("ABORT: " + m + "\nNothing was changed.")
    sys.exit(1)


def rollback():
    n = 0
    for p in EDITS:
        if os.path.exists(p + BAK):
            os.replace(p + BAK, p)
            n += 1
    for p in NEW:
        if os.path.exists(p):
            os.remove(p)
            n += 1
    if os.path.isdir("scripts/checklist") and not os.listdir("scripts/checklist"):
        os.rmdir("scripts/checklist")
    if os.path.exists(HOOK + BAK):
        os.replace(HOOK + BAK, HOOK)
    elif os.path.exists(CREATED_MARK) and os.path.exists(HOOK):
        os.remove(HOOK)
    if os.path.exists(CREATED_MARK):
        os.remove(CREATED_MARK)
    say(f"Rolled back {n} file(s)." if n else "Nothing to roll back.")


def run_tests():
    bad = []
    for t in ("scripts/test_precommit_hooks.py", "scripts/test_reliability_checklist.py"):
        r = subprocess.run([sys.executable, t], capture_output=True, text=True)
        for ln in (r.stdout + r.stderr).splitlines():
            if "FAIL" in ln or "PASSED" in ln or "Traceback" in ln:
                say(ln)
        if r.returncode:
            bad.append(t)
    return bad


def precommit_cmd():
    for c in (["pre-commit"], [sys.executable, "-m", "pre_commit"]):
        try:
            if subprocess.run(c + ["--version"], capture_output=True).returncode == 0:
                return c
        except OSError:
            pass
    return None


def main():
    if not (os.path.exists(".pre-commit-config.yaml") and os.path.isdir(".git")):
        die("run this from the repo root (the folder with .pre-commit-config.yaml and .git).")
    if "--rollback" in sys.argv:
        rollback()
        return 0
    cfg = open(".pre-commit-config.yaml", encoding="utf-8").read()
    if FENCE in cfg:
        say(f"{FENCE} already applied — nothing to do.")
        return 0
    if PARENT not in cfg:
        die(f"parent fence {PARENT} not found (run apply_push_anytime.py first).")
    st = subprocess.run(["git", "status", "--porcelain", "--", *EDITS, *NEW], capture_output=True, text=True)
    if st.returncode:
        die("git status failed: " + st.stderr.strip())
    if st.stdout.strip():
        die("these paths have uncommitted changes or already exist (commit, stash or remove them):\n" + st.stdout)
    for p in EDITS:
        if not os.path.exists(p):
            die(f"{p} is missing.")
        if os.path.exists(p + BAK):
            die(f"{p + BAK} exists from an earlier try — run --rollback or delete it.")
    for p in NEW:
        if os.path.exists(p):
            die(f"{p} already exists.")

    new = {}
    for p, eds in EDITS.items():
        s = open(p, encoding="utf-8").read()
        for old, rep in eds:
            c = s.count(old)
            if c != 1:
                die(f"{p}: expected text found {c} times (file differs from main): {old[:70]!r}")
            s = s.replace(old, rep, 1)
        new[p] = s
    with tempfile.TemporaryDirectory() as d:
        for p, s in list(new.items()) + list(NEW.items()):
            if p.endswith(".py"):
                t = os.path.join(d, p.replace("/", "_"))
                open(t, "w", encoding="utf-8").write(s)
                try:
                    py_compile.compile(t, doraise=True)
                except py_compile.PyCompileError as e:
                    die(f"{p} does not compile: {e}")

    try:
        for p, s in new.items():
            stg = p + ".staging-" + FENCE
            with open(stg, "w", encoding="utf-8", newline="") as f:
                f.write(s)
            shutil.copy2(p, p + BAK)
            shutil.copymode(p, stg)
            os.replace(stg, p)
        for p, s in NEW.items():
            os.makedirs(os.path.dirname(p), exist_ok=True)
            with open(p, "w", encoding="utf-8", newline="") as f:
                f.write(s)
            if p in EXEC:
                os.chmod(p, 0o755)
    except Exception as e:  # all-or-nothing
        for p in new:
            if os.path.exists(p + ".staging-" + FENCE):
                os.remove(p + ".staging-" + FENCE)
        rollback()
        die(f"write failed ({e}); restored.")

    bad = run_tests()
    if bad:
        rollback()
        die("tests failed after the change: " + ", ".join(bad) + "; restored.")

    pc = os.path.join(".git", "hooks", "pre-commit")
    installed = os.path.exists(pc) and "pre-commit" in open(pc, encoding="utf-8", errors="replace").read()
    cmd = precommit_cmd()
    if installed and cmd:
        if os.path.exists(HOOK):
            shutil.copy2(HOOK, HOOK + BAK)
        else:
            open(CREATED_MARK, "w").close()
        r = subprocess.run(cmd + ["install"], capture_output=True, text=True)
        say("pre-commit install: " + (r.stdout.strip().splitlines() or ["(no output)"])[-1])
    else:
        say("pre-commit is not set up in this clone — run once:  pre-commit install")

    say(f"\n{FENCE} applied. Mode: observe (never blocks).")
    say("Every commit now ends with a 'Checklist: …' line. See the items: "
        "python3 scripts/hooks/reliability_checklist.py --list")
    say("After a week or two: python3 scripts/hooks/reliability_checklist.py --report, "
        "then switch to enforce by writing 'enforce' into scripts/checklist/MODE and committing it.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
